WITH with_windows AS (SELECT id, country, LEAD(rating) OVER (PARTITION BY country, city ORDER BY rating, id) AS next_rating, LAG(rating) OVER (PARTITION BY country, city ORDER BY rating, id) AS prev_rating, ROW_NUMBER() OVER (PARTITION BY country, city ORDER BY rating, id) AS row_seq, FIRST_VALUE(rating) IGNORE NULLS OVER (ORDER BY rating, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_rating FROM suppliers) SELECT CASE WHEN prev_rating >= 4.0 THEN 'LARGE' ELSE 'SMALL' END AS prev_rating_tier, CASE WHEN next_rating >= 4.5 THEN 'LARGE' ELSE 'SMALL' END AS next_rating_tier, COUNT(*) FILTER (WHERE country = 'DE') AS de_rows, COUNT_IF(country = 'US') AS us_events, SUM(prev_rating) FILTER (WHERE country = 'US') AS us_total_prev_rating, AVG(first_known_rating) AS avg_first_known_rating, COUNT(DISTINCT id) AS distinct_ids FROM with_windows GROUP BY ROLLUP (CASE WHEN prev_rating >= 4.0 THEN 'LARGE' ELSE 'SMALL' END, CASE WHEN next_rating >= 4.5 THEN 'LARGE' ELSE 'SMALL' END) HAVING us_events > 1 ORDER BY distinct_ids
